package com.secure.documentwallet;

import android.content.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;

/** Explains current account access honestly until server-side device sessions are introduced. */
public class AccountDevicesActivity extends FragmentActivity {
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}LinearLayout page=VaultPageUi.page(this);page.addView(VaultPageUi.header(this,"Backup Account And PC Access","Where your encrypted vault can be opened"));page.addView(VaultPageUi.section(this,"This Phone"));String model=Build.MANUFACTURER+" "+Build.MODEL;VaultPageUi.addRow(page,VaultPageUi.iconRow(this,"user",model,"Local vault · Active now"));page.addView(VaultPageUi.section(this,"PC Portal"));LinearLayout portal=VaultPageUi.iconRow(this,"folder","Open My Vault On A Computer","Email verification and your recovery code are required every time");portal.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://badimps.github.io/secure-document-wallet/"))));VaultPageUi.addRow(page,portal);page.addView(VaultPageUi.notice(this,"info","No paired-device list yet","The portal does not create a permanent device pairing. Closing or hiding the browser locks it.",Ui.SOFT,Ui.TEAL));page.addView(VaultPageUi.section(this,"Account Safety"));page.addView(VaultPageUi.notice(this,"shield","Keep Your Recovery Code Private","Anyone with email access and this code can open a cloud backup. Create a replacement code if it may have been exposed.",0xfffff3dc,0xffb76a07));TextView open=VaultPageUi.primary(this,"Open Secure PC Portal");open.setOnClickListener(v->portal.performClick());VaultPageUi.button(page,open);setContentView(VaultPageUi.screen(this,page,"profile"));}
}
